function balancedBlueprint(plan) {
    let current = plan;
    let changed = true;
    while (changed) {
        changed = false;
        for (const pair of ["()", "[]", "{}"]) {
            const shorter = current.split(pair).join("");
            if (shorter.length !== current.length) {
                current = shorter;
                changed = true;
            }
        }
    }
    return current.length === 0;
}

function balancedBlueprint(plan) {
    const closerFor = { "(": ")", "[": "]", "{": "}" };
    const expected = [];
    for (const symbol of plan) {
        if (symbol in closerFor)
            expected.push(closerFor[symbol]);
        else if (expected.pop() !== symbol)
            return false;
    }
    return expected.length === 0;
}
